class UPSPriceDiscPriceAttributeGroupSearch extends RunBase
{
    UPSPriceAttributeGroupSearchTmp priceAttributeGroupSearchTmp;

    FromDate            fromDate;
    ToDate              toDate;
    CurrencyCode        currencyCode;
    PriceDiscJournalNum journalNum;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        fromDate,
        toDate,
        currencyCode,
        journalNum,
        priceAttributeGroupSearchTmp
    #endmacro

}

Method.Source:
Object  dialog(DialogRunbase _dialog = null, boolean _forceOnClient = false)
{
    DialogRunbase   dialog = Dialog::newFormnameRunbase(formStr(UPSPriceDiscPriceAttributeGroupSearch),this);
    dialog = this.dialogInternal(dialog);
    return dialog;
}

public UPSPriceAttributeGroupSearchTmp parmPriceAttributeGroupSearchTmp(UPSPriceAttributeGroupSearchTmp _priceAttributeGroupSearchTmp = priceAttributeGroupSearchTmp)
{
    priceAttributeGroupSearchTmp = _priceAttributeGroupSearchTmp;

    return priceAttributeGroupSearchTmp;
}

public CurrencyCode parmCurrencyCode(CurrencyCode _currencyCode = currencyCode)
{
    currencyCode = _currencyCode;

    return currencyCode;
}

public FromDate parmFromDate(FromDate _fromDate = fromDate)
{
    fromDate = _fromDate;

    return fromDate;
}

ToDate parmToDate(ToDate _toDate = toDate)
{
    toDate = _toDate;

    return toDate;
}

public static UPSPriceDiscPriceAttributeGroupSearch construct()
{
    return new UPSPriceDiscPriceAttributeGroupSearch();
}

static void  main(Args  _args)
{
    if (!(_args.dataset() == tableNum(PriceDiscAdmTrans)))
    {
        throw error("@SYS18626");
    }

    PriceDiscAdmTrans                       priceDiscAdmTrans = _args.record();
    UPSPriceDiscPriceAttributeGroupSearch   priceDiscSearch = UPSPriceDiscPriceAttributeGroupSearch::construct();

    priceDiscSearch.getLast();
    if (!priceDiscAdmTrans.JournalNum)
    {
        FormRun  priceDiscTransForm = _args.caller();

        if (   !(priceDiscTransForm is FormRun)
               || !(priceDiscTransForm.args().caller() is FormRun))
        {
            throw error("@SYS18626");
        }

        FormRun         priceDiscTableForm = priceDiscTransForm.args().caller();
        FormDataSource  tableDataSource    = priceDiscTableForm.dataSource();

        if (tableDataSource.table() != tableNum(PriceDiscAdmTable))
        {
            throw error("@SYS18626");
        }
        else
        {
            PriceDiscAdmTable priceDiscAdmTable = tableDataSource.cursor();
            priceDiscSearch.initJournalNum(priceDiscAdmTable.JournalNum);
        }
    }
    else
    {
        priceDiscSearch.initJournalNum(priceDiscAdmTrans.JournalNum);
    }

    if (priceDiscSearch.prompt())
    {
        priceDiscSearch.runOperation();

        if (priceDiscAdmTrans.dataSource())
        {
            priceDiscAdmTrans.dataSource().research(true);
            priceDiscAdmTrans.dataSource().refresh();
        }
    }
}

/// <summary>
///    Contains the code that does the actual job of the class.
/// </summary>
void  run()
{
    PriceDiscAdmTrans priceDiscAdmTrans;
    PriceDiscTable priceDiscTable;
    RecordInsertList rilpriceDiscAdmTrans = new RecordInsertList(tableNum(PriceDiscAdmTrans));

    ttsbegin;

    QueryRun qRun = new QueryRun(this.buildQuery());

    while (qRun.next())
    {
        priceDiscTable = qRun.get(tableNum(PriceDiscTable));

        priceDiscAdmTrans.clear();
        priceDiscAdmTrans.initFromPriceDiscTable(priceDiscTable);
        priceDiscAdmTrans.JournalNum = journalNum;

        rilpriceDiscAdmTrans.add(priceDiscAdmTrans);
    }

    rilpriceDiscAdmTrans.insertDatabase();

    ttscommit;
}

private Query buildQuery()
{
    Query searchQuery = new Query();
    QueryBuildDataSource qbdsPriceDiscTable;

    qbdsPriceDiscTable = searchQuery.addDataSource(tableNum(PriceDiscTable));
    qbdsPriceDiscTable.addRange(fieldNum(PriceDiscTable, relation)).value(queryValue(PriceType::PriceSales));
    qbdsPriceDiscTable.addRange(fieldNum(PriceDiscTable, AccountCode)).value(queryValue(PriceDiscProductCodeType::All));
    qbdsPriceDiscTable.addRange(fieldNum(PriceDiscTable, Currency)).value(currencyCode);

    if (toDate)
    {
        qbdsPriceDiscTable.addRange(fieldNum(PriceDiscTable, FromDate)).value(queryRange(null, toDate));
    }
    if (fromDate)
    {
        qbdsPriceDiscTable.addRange(fieldNum(PriceDiscTable, ToDate)).value(queryRange(fromDate, null));
        qbdsPriceDiscTable.addRange(fieldNum(PriceDiscTable, ToDate)).value(queryValue(dateNull()));
    }

    this.addPricingRuleDataSource(qbdsPriceDiscTable);
    this.addPriceDiscAdmTransDataSource(qbdsPriceDiscTable);

    return searchQuery;
}

/// <summary>
/// Joins the <c>PriceDiscAdmTrans</c> to the <c>PriceDiscTable</c> data source.
/// </summary>
/// <param name = "_qbdsPriceDiscTable"><c>PriceDiscTable</c> data source</param>
private void addPriceDiscAdmTransDataSource(QueryBuildDataSource _qbdsPriceDiscTable)
{
    QueryBuildDataSource qbdsPriceDiscAdmTrans = _qbdsPriceDiscTable.addDataSource(tableNum(PriceDiscAdmTrans));
    qbdsPriceDiscAdmTrans.relations(false);
    qbdsPriceDiscAdmTrans.fetchMode(QueryFetchMode::One2One);
    qbdsPriceDiscAdmTrans.joinMode(JoinMode::NoExistsJoin);
    qbdsPriceDiscAdmTrans.addRange(fieldNum(PriceDiscAdmTrans, JournalNum)).value(queryValue(journalNum));
    qbdsPriceDiscAdmTrans.addLink(fieldNum(PriceDiscTable, RecId), fieldNum(PriceDiscAdmTrans, PriceDiscTableRef), _qbdsPriceDiscTable.name());
}

/// <summary>
/// Joins the <c>UPSPricingRule</c> to the <c>PriceDiscTable</c> data source.
/// </summary>
/// <param name = "_qbdsPriceDiscTable"><c>PriceDiscTable</c> data source</param>
private void addPricingRuleDataSource(QueryBuildDataSource _qbdsPriceDiscTable)
{        
    QueryBuildDataSource qbdsPricingRuleHeader = _qbdsPriceDiscTable.addDataSource(tableNum(UPSPricingRule));
    qbdsPricingRuleHeader.fetchMode(QueryFetchMode::One2One);
    qbdsPricingRuleHeader.joinMode(JoinMode::ExistsJoin);
    qbdsPricingRuleHeader.addLink(fieldNum(PriceDiscTable, PricingRuleHeader), fieldNum(UPSPricingRule, RecID), _qbdsPriceDiscTable.name());

    if (priceAttributeGroupSearchTmp.PricingGroupCodeHeader == UPSGroupAll::Group)
    {
        qbdsPricingRuleHeader.addRange(fieldNum(UPSPricingRule, PriceAttributeGroup)).value(queryValue(priceAttributeGroupSearchTmp.PricingAttributeGroupHeader));
    }

    QueryBuildDataSource qbdsPricingRuleLine = _qbdsPriceDiscTable.addDataSource(tableNum(UPSPricingRule));
    qbdsPricingRuleLine.fetchMode(QueryFetchMode::One2One);
    qbdsPricingRuleLine.joinMode(JoinMode::ExistsJoin);
    qbdsPricingRuleLine.addLink(fieldNum(PriceDiscTable, PricingRuleLine), fieldNum(UPSPricingRule, RecID), _qbdsPriceDiscTable.name());        

    if (priceAttributeGroupSearchTmp.PricingGroupCodeLine == UPSGroupAll::Group)
    {
        qbdsPricingRuleLine.addRange(fieldNum(UPSPricingRule, PriceAttributeGroup)).value(queryValue(priceAttributeGroupSearchTmp.PricingAttributeGroupLine));
    }
}

boolean  unpack(container  packedClass)
{
    Integer     version = RunBase::getVersion(packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = packedClass;
            break;

        default:
            return false;
    }
    return true;
}
